(1, 'Alumni Registration & Initial Survey', 'Welcome! This survey helps us collect your information and track your career progress.', 'Please fill out all required fields. This information will be used to create your alumni profile.', 'active', 'registration', NULL, NULL, NULL, NULL, 0, 0, 0, 1, 'Complete Your Alumni Registration', 'Dear Alumni, Please complete your registration by clicking the link below.', 0, 7, 0, 2, 0.00, 1, '2025-09-07 22:32:18', '2025-11-19 22:07:50'),
(3, 'Test', 'Test', NULL, 'draft', 'custom', '2025-09-18 00:00:00', '2025-09-19 00:00:00', '[]', '[]', 0, 0, 1, 0, NULL, NULL, 0, 7, 0, 0, 0.00, 13, '2025-09-17 23:23:04', '2025-09-17 23:23:04'),
(5, 'Alumni Employment & Job Satisfaction Survey', 'Help us understand how well your education prepared you for your career and your current job satisfaction.', 'Please answer the following questions about your current employment situation. Your responses will help us improve our programs.', 'active', 'follow_up', '2025-10-08 06:33:21', '2026-04-08 06:33:21', NULL, NULL, 0, 0, 1, 0, 'Share Your Employment Experience - Alumni Survey', 'Dear Alumni,\r\n\r\nWe would like to hear about your current employment situation and how well your education prepared you for your career. Your feedback is valuable in helping us improve our programs.\r\n\r\nPlease take a few minutes to complete this survey.\r\n\r\nBest regards,\r\nAlumni Relations Office', 1, 14, 0, 0, 0.00, 1, '2025-10-07 22:33:21', '2025-10-07 22:33:21'),
(6, 'Employment Quality & Job Satisfaction Survey', 'Help us understand how well your education prepared you for your career and your current job satisfaction.', 'Please answer the following questions about your current employment. This information helps us improve our programs and better prepare future graduates.', 'active', 'follow_up', '2025-10-08 06:42:47', '2026-04-08 06:42:47', NULL, NULL, 0, 0, 1, 0, NULL, NULL, 1, 7, 0, 0, 0.00, 1, '2025-10-07 22:42:47', '2025-10-07 22:42:47'),
